sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var P = 'x_2056099_indust_0_';
    var custSysId = '{{step['4dc0b2bf855a459cac2a14c1729385f9'].record_id}}';
    var prodSysId = '{{step['c8c5fb5c887b4c01bb6732b2ad5df397'].record_id}}';
    var orderSysId = '', itemSysId = '';
    try {
        var grOrder = new GlideRecord(P + 'cust_order');
        grOrder.initialize();
        grOrder.setValue('customer', custSysId);
        grOrder.setValue('order_date', new GlideDateTime().getValue());
        grOrder.setValue('requested_delivery_date', new GlideDateTime().getValue());
        grOrder.setValue('status', 'draft');
        grOrder.setValue('order_type', 'standard');
        grOrder.setValue('priority', 'medium');
        grOrder.setValue('active', true);
        orderSysId = grOrder.insert();
        assertEqual({ name: 'Order created', shouldbe: true, value: orderSysId.length > 0 });
        var grOC = new GlideRecord(P + 'cust_order');
        grOC.get(orderSysId);
        assertEqual({ name: 'Order belongs to customer', shouldbe: custSysId, value: grOC.getValue('customer') });
        assertEqual({ name: 'Order number generated', shouldbe: true, value: (grOC.getValue('number') || '').length > 0 });
        assertEqual({ name: 'Initial status stored', shouldbe: true, value: (grOC.getValue('status') || '').length > 0 });
        var grItem = new GlideRecord(P + 'cust_ord_item');
        grItem.initialize();
        grItem.setValue('customer_order', orderSysId);
        grItem.setValue('material_product', prodSysId);
        grItem.setValue('quantity_ordered', 10);
        grItem.setValue('unit_of_measure', 'EA');
        grItem.setValue('active', true);
        itemSysId = grItem.insert();
        assertEqual({ name: 'Order item created', shouldbe: true, value: itemSysId.length > 0 });
        var grIC = new GlideRecord(P + 'cust_ord_item');
        grIC.get(itemSysId);
        assertEqual({ name: 'Correct product on item', shouldbe: prodSysId, value: grIC.getValue('material_product') });
        assertEqual({ name: 'Correct quantity', shouldbe: '10', value: grIC.getValue('quantity_ordered') });
        assertEqual({ name: 'Item linked to order', shouldbe: orderSysId, value: grIC.getValue('customer_order') });
        stepResult.setOutputMessage('Order: ' + grOC.getValue('number') + ' Items:1 Qty:10');
    } finally {
        if (itemSysId) { var d1 = new GlideRecord(P + 'cust_ord_item'); if (d1.get(itemSysId)) d1.deleteRecord(); }
        if (orderSysId) { var d2 = new GlideRecord(P + 'cust_order'); if (d2.get(orderSysId)) d2.deleteRecord(); }
    }
    return true;
})(outputs, steps, params, stepResult, assertEqual);
